smart.css:
.smc-root {
  container-name: smc;
  container-type: inline-size;
  max-width: 900px;
  margin: 0 auto;
  color: var(--smc-text);
  background: var(--smc-bg);
  font-family: var(--smc-font-body);
  font-size: 16px;
  line-height: 1.75;
}

.smc-root * {
  box-sizing: border-box;
}

.smc-root .smc-section {
  margin: 0 0 32px;
  padding: 0;
}

.smc-root .smc-intro {
  padding: 22px;
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  background: color-mix(in srgb, var(--smc-primary) 4%, var(--smc-bg));
}

.smc-root .smc-eyebrow {
  margin: 0 0 8px;
  color: var(--smc-primary);
  font-family: var(--smc-font-body);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1.5;
  text-transform: uppercase;
}

.smc-root .smc-heading {
  margin: 0 0 14px;
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-size: 28px;
  font-weight: 700;
  line-height: 1.28;
}

.smc-root .smc-lead {
  margin: 0 0 12px;
  color: var(--smc-text);
  font-family: var(--smc-font-body);
  font-size: 18px;
  line-height: 1.7;
}

.smc-root .smc-copy {
  margin: 0 0 14px;
  color: var(--smc-text);
  font-family: var(--smc-font-body);
  font-size: 16px;
  line-height: 1.75;
}

.smc-root .smc-figure {
  width: 100%;
  max-width: 590px;
  margin: 18px auto 4px;
  padding: 0;
  text-align: center;
}

.smc-root .smc-figure img {
  display: block;
  width: 100%;
  max-width: 590px;
  height: auto;
  margin: 0 auto;
  border-radius: var(--smc-radius);
}

.smc-root .smc-caption {
  margin: 8px auto 0;
  color: var(--smc-muted);
  font-family: var(--smc-font-body);
  font-size: 14px;
  line-height: 1.55;
  text-align: center;
}

.smc-root .smc-note,
.smc-root .smc-price-note {
  margin: 18px 0 0;
  padding: 18px 20px;
  border-left: 4px solid var(--smc-accent);
  border-radius: 0 var(--smc-radius) var(--smc-radius) 0;
  background: color-mix(in srgb, var(--smc-accent) 6%, var(--smc-bg));
}

.smc-root .smc-note-title {
  margin: 0 0 8px;
  color: var(--smc-accent);
  font-family: var(--smc-font-heading);
  font-size: 18px;
  font-weight: 700;
  line-height: 1.4;
}

.smc-root .smc-note .smc-copy:last-child,
.smc-root .smc-price-note .smc-copy:last-child {
  margin-bottom: 0;
}

.smc-root .smc-price-section {
  padding: 20px;
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  background: var(--smc-surface);
}

.smc-root .smc-price-note {
  margin-top: 8px;
}

.smc-root .smc-conclusion {
  padding: 20px;
  border-radius: var(--smc-radius);
  background: color-mix(in srgb, var(--smc-primary) 5%, var(--smc-bg));
}

.smc-root .smc-section:last-child .smc-copy:last-child {
  margin-bottom: 0;
}

@container smc (max-width: 620px) {
  .smc-root {
    font-size: 15px;
    line-height: 1.7;
  }

  .smc-root .smc-section {
    margin-bottom: 24px;
  }

  .smc-root .smc-intro,
  .smc-root .smc-price-section,
  .smc-root .smc-conclusion {
    padding: 16px;
  }

  .smc-root .smc-heading {
    margin-bottom: 12px;
    font-size: 23px;
  }

  .smc-root .smc-lead {
    font-size: 17px;
  }

  .smc-root .smc-copy {
    font-size: 15px;
    margin-bottom: 12px;
  }

  .smc-root .smc-note,
  .smc-root .smc-price-note {
    padding: 14px 15px;
  }
}

